create table if not exists salary_grades (id uuid primary key default gen_random_uuid(), grade text not null, position text, monthly_salary numeric(14,2) not null, created_at timestamptz not null default now()); create table if not exists compensation_adjustments (id uuid primary key default gen_random_uuid(), employee_id uuid not null references employees(id), adjustment_type text not null, amount numeric(14,2) not null, reason text, status text not null default 'Pending', created_at timestamptz not null default now());
